		until lsof -ti :8080 -sTCP:LISTEN > /dev/null && lsof -ti :9099 -sTCP:LISTEN > /dev/null; do \
			sleep 1; \
		done; \
	else \
		echo "Firebase Emulators already running"; \
	fi

