	if [ -f .check.sha256 ] && [ "$$CURRENT_HASH" = "$$(cat .check.sha256)" ]; then \
		echo "Code matches cached check. Skipping duplicate checks..."; \
	else \
		$(MAKE) _run-checks || exit 1; \
		echo "All checks passed! Caching result..."; \
		$(CHECK_HASH_CMD) > .check.sha256; \
	fi

