/// Product status based on expiration date
enum ProductStatus {
  fresh,
  expiringSoon,
  expired;

  /// Get status color for the given color scheme
  Color getColor(ColorScheme colorScheme) {
    switch (this) {
      case ProductStatus.fresh:
        return colorScheme.primary;
      case ProductStatus.expiringSoon:
        return colorScheme.tertiary;
      case ProductStatus.expired:
        return colorScheme.error;
    }
  }

  /// Get status message
  String getMessage() {
    switch (this) {
      case ProductStatus.fresh:
        return 'product.status_fresh'.tr();
      case ProductStatus.expiringSoon:
        return 'product.status_expires_soon'.tr();
      case ProductStatus.expired:
        return 'product.status_expired'.tr();
    }
  }

  /// Get status icon
  IconData getIcon() {
    switch (this) {
      case ProductStatus.fresh:
        return Icons.check_circle_outline;
      case ProductStatus.expiringSoon:
        return Icons.warning_amber_rounded;
      case ProductStatus.expired:
        return Icons.error_outline;
    }
  }
}

/// Entry for a specific quantity expiring on a specific date
@freezed
abstract class ExpiryEntry with _$ExpiryEntry {
  const ExpiryEntry._();
  const factory ExpiryEntry({
    required int quantity,
    required DateTime expirationDate,
  }) = _ExpiryEntry;

  factory ExpiryEntry.fromJson(Map<String, Object?> json) =>
      _$ExpiryEntryFromJson(json);

  Map<String, dynamic> toFirestoreRest() {
    return {
      'mapValue': {
        'fields': {
          'quantity': {'integerValue': quantity.toString()},
          'expirationDate': {'stringValue': expirationDate.toIso8601String()},
        },
      },
    };
  }

  bool get isExpired {
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    final expiry = DateTime(
      expirationDate.year,
      expirationDate.month,
      expirationDate.day,
    );
    return expiry.isBefore(today);
  }

  bool get isExpiringToday {
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    final expiry = DateTime(
      expirationDate.year,
      expirationDate.month,
      expirationDate.day,
    );
    return expiry.isAtSameMomentAs(today);
  }

  int get daysUntilExpiration {
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    final expiry = DateTime(
      expirationDate.year,
      expirationDate.month,
      expirationDate.day,
    );
    return expiry.difference(today).inDays;
  }
}

@freezed
abstract class Product with _$Product {
  const Product._();
  const factory Product({
    required String id,
    required String name,
    required String description,
    required String userId, // Owner of the product
    @Default([])
    List<ExpiryEntry> expiries, // Quantities and their expiration dates
    @Default(0) int nonExpiringQuantity,
    String? category,
    String? imageUrl,
    String? barcode,
    @Default(false) bool isGlobal,

    /// registryType -> Scope in the shared `products` collection.
    /// - global: globally shared registry products
    /// - personal: user-owned registry products (templates)
    /// - current: concrete products used in inventories/shopping lists
    @Default('current') String registryType,
    String? mappedFromProductId,
    @Default([])
    List<String> tags, // Labels and tags from APIs like OpenFoodFacts
  }) = _Product;

  factory Product.fromJson(Map<String, Object?> json) =>
      _$ProductFromJson(json);

  // Helper method to get total quantity
  int get quantity =>
      nonExpiringQuantity +
      expiries.fold(0, (sum, entry) => sum + entry.quantity);

  // Helper method to get the soonest expiration date
  DateTime? get soonestExpirationDate {
    if (expiries.isEmpty) return null;
    return expiries
        .map((e) => e.expirationDate)
        .reduce((a, b) => a.isBefore(b) ? a : b);
  }

  // Helper method to check if any quantity is expired
  bool get isExpired {
    return expiries.any((e) => e.isExpired);
  }

  // Helper method to check if any quantity is expiring today
  bool get isExpiringToday {
    return expiries.any((e) => e.isExpiringToday);
  }

  // Helper method to check if any quantity is expiring soon (within 1–6 days)
  bool get isExpiringSoon {
    return expiries.any((e) {
      final days = e.daysUntilExpiration;
      return days > 0 && days <= 6;
    });
  }

  // Soonest days until expiration (negative if expired)
  int? get daysUntilExpiration {
    if (expiries.isEmpty) return null;
    return expiries
        .map((e) => e.daysUntilExpiration)
        .reduce((a, b) => a < b ? a : b);
  }

  // Get product status based on expiration
  ProductStatus get status {
    if (isExpired) return ProductStatus.expired;
    if (isExpiringToday || isExpiringSoon) return ProductStatus.expiringSoon;
    return ProductStatus.fresh;
  }

  /// Get a friendly status message for display
  String getFriendlyStatus({bool compact = false}) {
    final days = daysUntilExpiration;
    if (isExpired) {
      return compact
          ? 'product.status_compact_exp'.tr()
          : 'product.status_expired'.tr();
    }
    if (isExpiringToday) return 'product.status_today'.tr();
    if (days != null && days > 0) {
      return 'product.status_days_remaining'.tr(
        namedArgs: {'days': days.toString()},
      );
    }
    return status.getMessage();
  }

  Map<String, dynamic> toFirestoreRest() {
    return {
      'id': {'integerValue': id},
      'name': {'stringValue': name},
      'description': {'stringValue': description},
      'userId': {'stringValue': userId},
      'expiries': {
        'arrayValue': {
          'values': expiries.map((e) => e.toFirestoreRest()).toList(),
        },
      },
      'nonExpiringQuantity': {'integerValue': nonExpiringQuantity.toString()},
      'category': {'stringValue': category ?? ''},
      'imageUrl': {'stringValue': imageUrl ?? ''},
      'barcode': {'stringValue': barcode ?? ''},
      'isGlobal': {'booleanValue': isGlobal},
      'tags': {
        'arrayValue': {
          'values': tags.map((t) => {'stringValue': t}).toList(),
        },
      },
    };
  }
}
